window.LIB_LAZY=window.LIB_LAZY||{};
window.LIB_LAZY["eusebiu-istoria#185"]=[{"v":1,"t":"În această a șaptea carte a Istoriei Bisericii, marele episcop al Alexandriei, Dionisie, ne va ajuta din nou prin propriile lui cuvinte, povestind diferitele întâmplări ale vremii sale în epistolele pe care le-a lăsat. Cu ele voi începe."}];
window.LIB_LAZY["eusebiu-istoria#186"]=[{"v":1,"t":"Deciu, după ce a domnit puțin sub doi ani, a fost omorât împreună cu copiii lui și i-a urmat Gal. În acest timp a murit Origen, în vârstă de șaizeci și nouă de ani. Dionisie, scriind lui Hermammon, vorbește astfel despre Gal:"},{"v":2,"t":"„Gal nici nu a recunoscut răutatea lui Deciu, nici nu a luat în seamă ce l-a nimicit, ci s-a poticnit de aceeași piatră, deși zăcea înaintea ochilor lui. Căci pe când domnia lui era înfloritoare și treburile mergeau după mintea lui, a atacat pe oamenii sfinți care se rugau lui Dumnezeu pentru pacea și binele lui. De aceea a prigonit împreună cu ei și rugăciunile lor în favoarea lui.” Atât despre el."}];
window.LIB_LAZY["eusebiu-istoria#187"]=[{"v":1,"t":"Corneliu, după ce ținuse episcopia în cetatea Romei cam trei ani, a fost urmat de Luciu. Acesta a murit în mai puțin de opt luni și a transmis slujba lui Ștefan. Dionisie i-a scris cea dintâi dintre scrisorile sale despre botez, deoarece se ridicase o controversă nu mică dacă cei care se întorceau de la vreo erezie trebuiau curățiți prin botez. Căci obiceiul vechi stăpânea în privința unora ca aceștia, ca să primească doar punerea mâinilor cu rugăciuni."}];
window.LIB_LAZY["eusebiu-istoria#188"]=[{"v":1,"t":"Cel dintâi, Ciprian, păstorul parohiei Cartaginei, a susținut că nu trebuie primiți decât dacă au fost curățiți de rătăcirea lor prin botez. Dar Ștefan, socotind că nu este nevoie să se adauge vreo noutate împotriva tradiției ținute de la început, s-a indignat foarte mult din această pricină."}];
window.LIB_LAZY["eusebiu-istoria#189"]=[{"v":1,"t":"Dionisie, deci, după ce a vorbit cu el pe larg în această privință prin scrisori, i-a arătat în cele din urmă că, de când prigoana se potolise, bisericile de pretutindeni respinseseră noutatea lui Novat și erau în pace între ele. Scrie astfel:"}];
window.LIB_LAZY["eusebiu-istoria#190"]=[{"v":1,"t":"Dar să știți acum, frații mei, că toate bisericile din tot Răsăritul și de dincolo de el, care înainte erau dezbinate, s-au unit. Și toți episcopii de pretutindeni sunt într-un gând și se bucură mult de pacea venită dincolo de așteptare. Astfel Demetrian în Antiohia, Teoctist în Cezareea, Mazabane în Aelia, Marin în Tir (Alexandru adormind), Heliodor în Laodiceea (Telimidre fiind mort), Helen în Tars și toate bisericile Ciliciei, Firmilian și toată Capadocia. N-am numit decât pe episcopii mai însemnați, ca să nu fac epistola prea lungă și cuvintele mele prea grele."},{"v":2,"t":"Și toată Siria, și Arabia căreia îi trimiteți ajutor la nevoie și unde ați scris de curând, Mesopotamia, Pontul, Bitinia și, pe scurt, toți de pretutindeni se bucură și slăvesc pe Dumnezeu pentru unanimitate și dragostea frățească. Până aici Dionisie."},{"v":3,"t":"Dar Ștefan, după ce a ținut slujba doi ani, a fost urmat de Xyst. Dionisie i-a scris o a doua epistolă despre botez, în care îi arată totodată părerea și judecata lui Ștefan și a altor episcopi și vorbește astfel despre Ștefan:"},{"v":4,"t":"El scrisese, deci, mai înainte despre Helen și Firmilian și toți cei din Cilicia, Capadocia, Galatia și neamurile învecinate, spunând că nu se va împărtăși cu ei din aceeași pricină; anume, că rebotezau pe eretici. Dar gândiți-vă la însemnătatea chestiunii."},{"v":5,"t":"Căci într-adevăr, în cele mai mari sinoade ale episcopilor, după cum aflu, s-au dat hotărâri în această privință, ca cei care vin de la erezii să fie instruiți și apoi să fie spălați și curățiți de murdăria aluatului vechi și necurat. Și i-am scris rugându-l în privința tuturor acestor lucruri. Mai departe spune:"},{"v":6,"t":"„Am scris, la început în câteva cuvinte, apoi de curând în multe, iubiților noștri împreună-prezbiteri Dionisie și Filimon, care mai înainte ținuseră aceeași părere ca Ștefan și îmi scriseseră despre aceleași lucruri.” Atât în privința controversei pomenite."}];
window.LIB_LAZY["eusebiu-istoria#191"]=[{"v":1,"t":"Se referă în aceeași scrisoare și la învățăturile eretice ale lui Sabeliu, care în vremea lui deveneau însemnate, și spune:"},{"v":2,"t":"„Căci în privința învățăturii care se dezbate acum în Ptolemaida Pentapolei — care este nelegiuită și marcată de mare hulă împotriva Dumnezeului Atotțiitor, Tatăl, și a Domnului nostru Isus Hristos, și cuprinde multă necredință în privința Fiului Său Unul-Născut și Întâi-Născut al oricărei făpturi, Cuvântul care s-a făcut om, și o lipsă de înțelegere a Duhului Sfânt —, cum veneau la mine înștiințări din ambele părți și frați care discutau chestiunea, am scris câteva scrisori tratând subiectul cât de instructiv am putut, cu ajutorul lui Dumnezeu. Din acestea vă trimit copii.”"}];
window.LIB_LAZY["eusebiu-istoria#192"]=[{"v":1,"t":"În a treia epistolă despre botez, pe care același Dionisie a scris-o lui Filimon, prezbiterul roman, povestește următoarele: Dar am cercetat lucrările și tradițiile ereticilor, spurcându-mi mintea o scurtă vreme cu părerile lor scârboase, dar primind de la ei acest folos, că i-am combătut singur și i-am urât cu atât mai mult."},{"v":2,"t":"Și când un frate dintre prezbiteri m-a oprit, temându-se că voi fi dus de murdăria răutății lor (căci mi-ar spurca sufletul) — în care, după cum am văzut, spunea adevărul —, o vedenie trimisă de la Dumnezeu a venit și m-a întărit."},{"v":3,"t":"Și cuvântul care a venit la mine mi-a poruncit, spunând limpede: «Citește tot ce poți lua în mână, căci poți să îndrepți și să încerci toate; și aceasta a fost pentru tine de la început pricina credinței tale.» Am primit vedenia ca fiind în acord cu cuvântul apostolic, care spune celor mai tari: «Fiți schimbători de bani pricepuți.»"},{"v":4,"t":"Apoi, după ce spune unele lucruri despre toate ereziile, adaugă: „Am primit această regulă și rânduială de la fericitul nostru părinte Heraclas. Căci pe cei care veneau de la erezii, deși se depărtaseră de Biserică — sau, mai bine zis, nu se depărtaseră, ci păreau că se întâlnesc cu ei, dar erau învinuiți că recurg la vreun învățător mincinos — după ce îi izgonise din Biserică, nu îi primea înapoi, deși îl rugau, până nu raportaseră public tot ce auziseră de la potrivnicii lor; dar atunci îi primea fără să ceară de la ei un alt botez. Căci primiseră de la el mai înainte Duhul Sfânt.”"},{"v":5,"t":"Iarăși, după ce tratează temeinic întrebarea, adaugă: „Am aflat de asemenea că aceasta nu este o practică nouă introdusă numai în Africa, ci că încă de demult, în vremea episcopilor dinaintea noastră, această părere a fost adoptată în cele mai populate biserici și în sinoade ale fraților din Iconiu și Sinada și de mulți alții. Să răstorn sfaturile lor și să-i arunc în ceartă și vrajbă, nu pot îndura. Căci se spune: «Să nu muți hotarul aproapelui tău, pe care l-au pus părinții tăi.»” (Deuteronom 19:14)"},{"v":6,"t":"A patra epistolă a sa despre botez a fost scrisă lui Dionisie al Romei, care era atunci prezbiter, dar nu mult după aceea a primit episcopia acelei biserici. Este vădit din ce spune despre el Dionisie al Alexandriei că și acesta era un om învățat și minunat. Printre altele îi scrie astfel despre Novat:"}];
window.LIB_LAZY["eusebiu-istoria#193"]=[{"v":1,"t":"„Căci pe bună dreptate simțim ură față de Novațian, care a sfâșiat Biserica și a tras pe unii dintre frați în nelegiuire și hulă, a adus o învățătură nelegiuită despre Dumnezeu și a defăimat pe prea milostivul nostru Domn Isus Hristos ca nemilostiv. Și pe lângă toate acestea, leapădă sfântul botez și răstoarnă credința și mărturisirea care îl precedă și izgonește cu totul din ei Duhul Sfânt, dacă într-adevăr era vreo nădejde că va rămâne sau se va întoarce la ei.”"}];
window.LIB_LAZY["eusebiu-istoria#194"]=[{"v":1,"t":"A cincea epistolă a sa a fost scrisă lui Xyst, episcopul Romei. În ea, după ce spune multe împotriva ereticilor, povestește o întâmplare din vremea lui astfel: Căci într-adevăr, frate, am nevoie de sfat și îți cer părerea într-o chestiune care a ajuns la mine, temându-mă să nu fiu în rătăcire."},{"v":2,"t":"Căci unul dintre frații care se adună, socotit de mult timp credincios și care, înainte de hirotonirea mea, și cred că înainte de rânduirea fericitului Heraclas, făcea parte din adunare, era de față cu cei botezați de curând. Și când a auzit întrebările și răspunsurile, a venit la mine plângând și tânguindu-se; și căzând la picioarele mele, a mărturisit și a declarat că botezul cu care fusese botezat între eretici nu era de acest fel și nu semăna cu acesta în niciun chip, pentru că era plin de nelegiuire și hulă."},{"v":3,"t":"Și a spus că sufletul lui este acum străpuns de durere și că nu are îndrăzneala să-și ridice ochii către Dumnezeu, pentru că plecase de la acele cuvinte și fapte nelegiuite. Și din această pricină se ruga să primească această prea desăvârșită curățire, și primire, și har."},{"v":4,"t":"Dar eu nu am cutezat să fac aceasta; și am spus că îndelungata lui împărtășire este de ajuns pentru aceasta. Căci nu aș cuteza să înnoiesc de la început pe unul care auzise rostirea mulțumirii și se unise în repetarea Amin-ului; care stătuse lângă masă și își întinsese mâinile să primească hrana binecuvântată; și care o primise și se împărtășise multă vreme din trupul și sângele Domnului nostru Isus Hristos. Dar l-am îndemnat să aibă curaj și să se apropie de împărtășania sfinților cu credință tare și bună nădejde."},{"v":5,"t":"Dar el nu încetează să se tânguiască și se înfioară să se apropie de masă și abia, deși rugat, cutează să fie de față la rugăciuni."},{"v":6,"t":"Pe lângă acestea se păstrează și o altă epistolă a aceluiași om despre botez, adresată de el și de parohia lui lui Xyst și bisericii din Roma. În ea cercetează cu argumente întinse întrebarea dezbătută atunci. Și se mai păstrează încă una după acestea, adresată lui Dionisie al Romei, despre Lucian. Atât în legătură cu acestea."}];
window.LIB_LAZY["eusebiu-istoria#195"]=[{"v":1,"t":"Gal și ceilalți cârmuitori, după ce au ținut stăpânirea mai puțin de doi ani, au fost răsturnați, iar Valerian, împreună cu fiul său Galien, a primit imperiul. Împrejurările pe care Dionisie le povestește despre el le putem afla din epistola lui către Hermammon, în care dă următoarea relatare:"},{"v":2,"t":"Și tot astfel i se descoperă lui Ioan: «Căci i s-a dat», spune el, «o gură care rostea lucruri mari și hule; și i s-a dat putere timp de patruzeci și două de luni.» (Apocalipsa 13:5)"},{"v":3,"t":"Este minunat că ambele lucruri s-au petrecut sub Valerian; și este cu atât mai de remarcat în acest caz dacă ne gândim la purtarea lui de mai înainte, căci fusese blând și prietenos față de oamenii lui Dumnezeu, fiindcă niciunul dintre împărații dinaintea lui nu i-a tratat atât de bine și cu atâta bunăvoință; și nici măcar cei despre care se spunea deschis că sunt creștini nu i-au primit cu o ospitalitate și prietenie atât de vădite ca el la începutul domniei sale. Căci toată casa lui era plină de oameni cucernici și era o biserică a lui Dumnezeu."},{"v":4,"t":"Dar învățătorul și căpetenia sinagogii magilor din Egipt l-a convins să-și schimbe purtarea, îndemnându-l să omoare și să prigonească pe oamenii curați și sfinți, pentru că se împotriveau și stânjeneau descântecele stricate și scârboase. Căci sunt și au fost oameni care, fiind de față și fiind văzuți, deși doar respirau și vorbeau, puteau risipi sfaturile demonilor păcătoși. Și l-a îndemnat să practice inițieri și vrăjitorii scârboase și să aducă jertfe nepotrivite; să omoare copii nenumărați și să jertfească odraslele unor părinți nefericiți; să taie măruntaiele nou-născuților și să schilodească și să facă bucăți făpturile lui Dumnezeu, ca și cum prin astfel de practici ar putea dobândi fericirea."},{"v":5,"t":"Adaugă la aceasta următoarele: Strălucite, într-adevăr, au fost darurile de mulțumire pe care Macrian le-a adus pentru imperiul care era ținta nădejdilor sale. Se spune că fusese mai înainte ministrul general de finanțe al împăratului; totuși nu a făcut nimic vrednic de laudă sau de folos obștesc, ci a căzut sub cuvântul profetic:"},{"v":6,"t":"«Vai de cei ce prorocesc din inima lor și nu iau în seamă binele obștesc.» (Ezechiel 13:3) Căci nu a văzut purtarea de grijă obștească și nu a căutat judecata Celui care este mai înainte de toți, și prin toți, și peste toți. De aceea a devenit dușman al Bisericii Lui Catolice și s-a înstrăinat și s-a depărtat de îndurarea lui Dumnezeu și a fugit cât a putut mai departe de mântuirea lui. În aceasta și-a arătat adevărul propriului nume."},{"v":7,"t":"Și iarăși, mai departe, spune: Căci Valerian, fiind instigat la asemenea fapte de acest om, a fost dat insultelor și ocărilor, după cum s-a spus prin Isaia: «Ei și-au ales căile lor și urâciunile lor, în care s-a desfătat sufletul lor; și Eu voi alege rătăcirile lor și le voi da înapoi păcatele lor.» (Isaia 66:3-4)"},{"v":8,"t":"Dar acest om dorea cu nebunie împărăția, deși nevrednic de ea, și, neputând pune haina împărătească pe trupul lui schilod, i-a pus înainte pe cei doi fii ai lui să poarte păcatele tatălui lor. Căci despre ei era limpede declarația pe care a rostit-o Dumnezeu: «Care pedepsesc nelegiuirea părinților în copii până la al treilea și al patrulea neam al celor ce Mă urăsc.» (Exod 20:5)"},{"v":9,"t":"Căci îngrămădind pe capetele fiilor săi propriile lui pofte rele, în care avusese succes, a șters asupra lor propria lui răutate și ură față de Dumnezeu. Dionisie povestește acestea despre Valerian."}];
window.LIB_LAZY["eusebiu-istoria#196"]=[{"v":1,"t":"Cât despre prigoana care a bântuit cu atâta furie în domnia lui și suferințele pe care Dionisie, împreună cu alții, le-a îndurat din pricina cucerniciei față de Dumnezeul universului, vor arăta propriile lui cuvinte, pe care le-a scris ca răspuns lui Germanus, un episcop contemporan care încerca să-l calomnieze. Afirmația lui este următoarea:"},{"v":2,"t":"Într-adevăr, sunt în primejdia de a cădea într-o mare nebunie și prostie, fiind silit să povestesc minunata purtare de grijă a lui Dumnezeu față de noi. Dar fiindcă se spune că «este bine să ții ascunsă taina unui împărat, dar este cinstit să dezvălui lucrările lui Dumnezeu» (Tobit 12:7), mă voi măsura cu violența lui Germanus."},{"v":3,"t":"Nu am mers singur la Emilian; ci împreună-prezbiterul meu, Maxim, și diaconii Faust, Eusebiu și Chairemon și un frate care era de față din Roma au mers cu mine."},{"v":4,"t":"Dar Emilian nu mi-a spus la început: «Nu țineți adunări»; căci aceasta era de prisos pentru el și ultimul lucru pentru cel care căuta să îl împlinească pe primul. Căci nu îl preocupa adunarea noastră, ci ca noi înșine să nu fim creștini. Și mi-a poruncit să las aceasta; închipuindu-și că dacă mă voi întoarce eu, vor urma și ceilalți."},{"v":5,"t":"Dar i-am răspuns, nici nepotrivit, nici în multe cuvinte: «Trebuie să ascultăm de Dumnezeu mai mult decât de oameni.» (Fapte 5:29) Și am mărturisit deschis că mă închin singurului Dumnezeu și niciunui altul; și că nu mă voi întoarce de la aceasta și nu voi înceta niciodată să fiu creștin. Atunci ne-a poruncit să mergem într-un sat de lângă pustie, numit Chefro."},{"v":6,"t":"Dar ascultați chiar cuvintele care s-au rostit de ambele părți, așa cum au fost înregistrate: Dionisie, Faust, Maxim, Marcel și Chairemon fiind aduși la judecată, prefectul Emilian a spus:"},{"v":7,"t":"«Am discutat cu voi de-a dreptul despre clemența pe care v-au arătat-o stăpânitorii noștri; căci v-au dat prilejul să vă mântuiți, dacă vă veți întoarce la ceea ce este după fire și vă veți închina zeilor care păzesc imperiul lor și veți uita pe cei care sunt împotriva firii. Ce spuneți, deci, la aceasta? Căci nu cred că veți fi nerecunoscători bunătății lor, de vreme ce vă întorc spre o cale mai bună.»"},{"v":8,"t":"Dionisie a răspuns: «Nu toți oamenii se închină tuturor zeilor; ci fiecare celor pe care îi aprobă. Noi, deci, cinstim și ne închinăm unicului Dumnezeu, Făcătorul tuturor; care a dat imperiul prea-bineplăcutului lui Dumnezeu și august Valerian și lui Galien; și ne rugăm Lui neîncetat pentru imperiul lor, ca să rămână neclintit.»"},{"v":9,"t":"Prefectul Emilian le-a spus: «Dar cine vă oprește să vă închinați Lui, dacă este dumnezeu, împreună cu cei care sunt zei prin fire? Căci vi s-a poruncit să cinstiți zeii, și zeii pe care îi cunosc toți.» Dionisie a răspuns:"},{"v":10,"t":"«Nu ne închinăm niciunui altul.» Prefectul Emilian le-a spus: «Văd că sunteți deopotrivă nerecunoscători și nesimțitori față de bunătatea stăpânitorilor noștri. De aceea nu veți rămâne în această cetate. Ci veți fi trimiși în regiunile Libiei, într-un loc numit Chefro. Căci am ales acest loc din porunca stăpânitorilor noștri și nu vă va fi îngăduit în niciun chip nici vouă, nici altora, să țineți adunări sau să intrați în așa-numitele cimitire."},{"v":11,"t":"Dar dacă va fi văzut cineva în afara locului pe care l-am poruncit sau va fi găsit într-o adunare, își va aduce primejdie asupra lui. Căci pedeapsa potrivită nu va lipsi. Mergeți, deci, unde vi s-a poruncit.» „Și m-a grăbit să plec, deși eram bolnav, nelăsându-mi nici măcar o zi de răgaz. Ce prilej mai aveam, deci, fie să țin adunări, fie să nu țin?”"},{"v":12,"t":"Mai departe spune: Dar cu ajutorul Domnului nu am renunțat la adunarea deschisă. Ci i-am chemat cu atât mai sârguincios pe cei din cetate, ca și cum aș fi fost cu ei; fiind, ca să zic așa, «absent cu trupul, dar prezent cu duhul» (1 Corinteni 5:3). Dar în Chefro s-a adunat cu noi o mare biserică, a fraților care ne-au urmat din cetate și a celor care s-au alăturat nouă din Egipt; și acolo «Dumnezeu ne-a deschis o ușă pentru Cuvânt» (Coloseni 4:3)."},{"v":13,"t":"La început am fost prigoniți și bătuți cu pietre; dar după aceea nu puțini dintre păgâni au părăsit idolii și s-au întors la Dumnezeu. Căci până atunci nu auziseră Cuvântul, el fiind semănat atunci întâia oară de noi."},{"v":14,"t":"Și ca și cum Dumnezeu ne-ar fi adus la ei pentru aceasta, după ce am îndeplinit această slujire, ne-a mutat în alt loc. Căci Emilian, după cum s-a părut, dorea să ne transporte în locuri mai aspre și mai asemănătoare Libiei; așa că a poruncit să se adune din toate părțile în Mareotis și le-a rânduit sate diferite în toată țara. Dar nouă ne-a poruncit să fim așezați mai aproape de drumul mare, ca să fim prinși întâi. Căci, vădit, a rânduit și pregătit lucrurile în așa fel încât, oricând ar fi voit să ne prindă, să ne poată lua pe toți fără greutate."},{"v":15,"t":"Când mi s-a poruncit prima oară să merg la Chefro, nu știam unde este locul și abia dacă auzisem numele; totuși am mers de bunăvoie și cu voioșie. Dar când mi s-a spus că trebuie să mă mut în ținutul Colutionului, cei de față știu cum am fost mișcat."},{"v":16,"t":"Căci aici mă voi acuza pe mine însumi. La început am fost întristat și foarte tulburat; căci deși aceste locuri ne erau mai bine cunoscute și mai familiare, totuși ținutul era spus a fi lipsit de frați și de oameni de caracter și expus supărărilor călătorilor și năvălirilor tâlharilor."},{"v":17,"t":"Dar am fost mângâiat când frații mi-au amintit că era mai aproape de cetate și că, în timp ce Chefro ne dădea multă legătură cu frații din Egipt, așa încât puteam extinde Biserica mai larg, în acest loc, fiind mai aproape de cetate, ne vom bucura mai des de vederea celor cu adevărat iubiți și cei mai apropiați și mai dragi nouă. Căci vor veni și vor rămâne și se vor putea ține adunări speciale, ca în suburbiile mai îndepărtate. Și așa s-a și întâmplat. După alte chestiuni, scrie din nou astfel despre cele petrecute cu el:"},{"v":18,"t":"Germanus se laudă, într-adevăr, cu multe mărturisiri. Poate vorbi, chipurile, de multe adversități pe care le-a îndurat el însuși. Dar poate el număra atâtea câte putem noi, de sentințe, confiscări, proscrieri, jefuiri de averi, pierderi de demnități, disprețuiri ale slavei lumești, nepăsare față de lingușirile guvernatorilor și ale sfetnicilor, răbdare statornică față de amenințările potrivnicilor, de strigăte, de primejdii și prigoniri, rătăciri și nevoi și tot felul de necazuri, cum au venit peste mine sub Deciu și Sabin și cum continuă și acum sub Emilian? Dar unde a fost văzut Germanus? Și ce relatare există despre el?"},{"v":19,"t":"Dar mă întorc de la această mare nebunie în care cad din pricina lui Germanus. Și din aceeași pricină mă las de a da fraților care o știu o relatare a tuturor celor ce s-au petrecut."},{"v":20,"t":"Același scriitor, în epistola către Domițiu și Didim, pomenește unele amănunte ale prigoanei astfel: Fiindcă ai noștri sunt mulți și necunoscuți vouă, ar fi de prisos să dau numele lor; dar înțelegeți că bărbați și femei, tineri și bătrâni, fecioare și matroane, soldați și civili, de orice neam și vârstă, unii prin biciuire și foc, alții prin sabie, au biruit în luptă și și-au primit cununile."},{"v":21,"t":"Dar în cazul unora un timp foarte lung nu a fost de ajuns ca să se arate plăcuți Domnului; după cum, într-adevăr, pare și în cazul meu că nu a trecut încă destul timp. De aceea El m-a ținut pentru timpul pe care îl știe potrivit, spunând: «Într-un timp potrivit te-am ascultat și în ziua mântuirii te-am ajutat.» (Isaia 49:8)"},{"v":22,"t":"Căci fiindcă ați întrebat de treburile noastre și voiți să vă spunem în ce stare ne aflăm, ați auzit pe deplin că atunci când noi — adică eu, Gaiu, Faust, Petru și Pavel — am fost duși prizonieri de un sutaș și de magistrați, cu soldații și slujitorii lor, unele persoane din Mareotis au venit și ne-au târât cu de-a sila, căci nu voiam să le urmăm."},{"v":23,"t":"Dar acum eu, Gaiu și Petru suntem singuri, lipsiți de ceilalți frați și închiși într-un loc pustiu și uscat al Libiei, la trei zile de drum de Paretoniu."},{"v":24,"t":"Mai departe spune: Prezbiterii Maxim, Dioscor, Dimitrie și Luciu s-au ascuns în cetate și vizitează pe frați în taină; căci Faustin și Aquila, care sunt mai cunoscuți în lume, rătăcesc prin Egipt. Dar diaconii Faust, Eusebiu și Chairemon au supraviețuit celor care au murit în ciumă. Eusebiu este unul pe care Dumnezeu l-a întărit și l-a înzestrat de la început să îndeplinească cu energie slujirile pentru mărturisitorii întemnițați și să se îngrijească de primejdioasa sarcină de a pregăti pentru îngropare trupurile martirilor desăvârșiți și fericiți."},{"v":25,"t":"Căci, după cum am spus mai înainte, până în ziua de azi guvernatorul continuă să omoare în chip crunt pe cei aduși la judecată. Și pe unii îi nimicește prin chinuri, pe alții îi istovește prin închisoare și lanțuri; și nu îngăduie nimănui să se apropie de ei și cercetează dacă face cineva aceasta. Totuși Dumnezeu dă ușurare celor necăjiți prin râvna și stăruința fraților."},{"v":26,"t":"Până aici Dionisie. Dar trebuie știut că Eusebiu, pe care el îl numește diacon, a devenit în scurt timp episcop al bisericii din Laodiceea Siriei; iar Maxim, pe care îl pomenește ca fiind atunci prezbiter, i-a urmat lui Dionisie însuși ca episcop al Alexandriei. Dar Faust, care era cu el și care în acel timp se distingea prin mărturisirea sa, a fost păstrat până la prigoana din zilele noastre, când, fiind foarte bătrân și plin de zile, și-a încheiat viața prin martiriu, fiind decapitat. Astfel sunt cele petrecute atunci cu Dionisie."}];
window.LIB_LAZY["eusebiu-istoria#197"]=[{"v":1,"t":"În timpul prigoanei pomenite sub Valerian, trei bărbați din Cezareea Palestinei, însemnați în mărturisirea lui Hristos, au fost împodobiți cu martiriul dumnezeiesc, devenind hrană pentru fiare sălbatice. Unul se numea Priscus, altul Malh, iar numele celui de-al treilea era Alexandru. Se spune că acești oameni, care trăiau la țară, s-au purtat la început fricos, ca și cum ar fi fost nepăsători și nechibzuiți. Căci atunci când li s-a dat prilejul celor care râvneau premiul cu dorință cerească, l-au luat ușor, ca să nu apuce prea devreme Cununa martiriului. Dar chibzuind asupra chestiunii, s-au grăbit la Cezareea și s-au înfățișat înaintea judecătorului și au întâmpinat sfârșitul pe care l-am pomenit. Povestesc că, pe lângă aceștia, în aceeași prigoană și în aceeași cetate, o anume femeie a îndurat o luptă asemănătoare. Dar se spune că ea ținea de secta lui Marcion."}];
window.LIB_LAZY["eusebiu-istoria#198"]=[{"v":1,"t":"Nu mult după aceasta Valerian a fost redus la robie de barbari, iar fiul său, rămas singur stăpânitor, a condus cârmuirea mai chibzuit. A oprit îndată prigoana împotriva noastră prin proclamații publice și a poruncit episcopilor să-și îndeplinească în libertate îndatoririle obișnuite, într-un rescript care suna astfel:"},{"v":2,"t":"„Împăratul Cezar Publiu Licinius Galien, Cucernicul, Fericitul, Augustul, către Dionisie, Pinnas, Dimitrie și ceilalți episcopi. Am poruncit ca darul bunăvoinței mele să fie vestit în toată lumea, ca ei să poată pleca din locurile de închinare religioasă. Și pentru aceasta puteți folosi această copie a rescriptului meu, ca nimeni să nu vă supere. Și ceea ce vi se îngăduie acum să faceți legal, v-am îngăduit eu de mult timp. De aceea Aureliu Cirenius, care este administratorul principal al treburilor, va păzi această rânduială pe care am dat-o.”"},{"v":3,"t":"Am dat aceasta în traducere din latină, ca să fie mai ușor de înțeles. Se păstrează și un alt decret al lui, adresat altor episcopi, îngăduindu-le să ia din nou în stăpânire așa-numitele cimitire."}];
window.LIB_LAZY["eusebiu-istoria#199"]=[{"v":1,"t":"În acel timp Xyst păstorea încă biserica Romei, Demetrian, urmașul lui Fabiu, biserica Antiohiei, și Firmilian pe cea a Cezareei Capadociei; și pe lângă aceștia, Grigorie și fratele său Atenodor, prietenii lui Origen, păstoreau bisericile din Pont; iar Teoctist al Cezareei Palestinei murind, Domn a primit acolo episcopia. A ținut-o doar puțin timp și i-a urmat Teotecn, contemporanul nostru. Și acesta a fost membru al școlii lui Origen. Dar în Ierusalim, după moartea lui Mazabane, i-a urmat în scaun Imeneu, care a fost vestit între noi o mulțime de ani."}];
window.LIB_LAZY["eusebiu-istoria#200"]=[{"v":1,"t":"În acest timp, când pacea bisericilor fusese pretutindeni restabilită, Marin din Cezareea Palestinei, care era cinstit pentru faptele sale militare și strălucit prin neam și avere, a fost decapitat pentru mărturia lui despre Hristos, din următoarea pricină."},{"v":2,"t":"Ramura de viță este un anumit semn de onoare la romani, iar cei care o dobândesc devin, se spune, sutași. Un loc rămânând liber, ordinea succesiunii l-a chemat pe Marin la această poziție. Dar când era pe cale să primească onoarea, altcineva s-a înfățișat la tribunal și a susținut că nu este legal, după legile vechi, ca el să primească demnitatea romană, fiind creștin și nejertfind împăraților; ci că slujba i se cuvine mai degrabă lui."},{"v":3,"t":"Atunci judecătorul, al cărui nume era Aheu, tulburându-se, a întrebat mai întâi ce părere are Marin. Și când a văzut că se mărturisește neîncetat creștin, i-a dat trei ceasuri de gândire."},{"v":4,"t":"Când a ieșit de la tribunal, Teotecn, episcopul de acolo, l-a luat deoparte și a vorbit cu el și, luându-l de mână, l-a dus în biserică. Și stând cu el înăuntru, în altar, i-a ridicat puțin mantaua și a arătat sabia care atârna la coapsa lui; și totodată a pus înaintea lui Scriptura dumnezeieștilor Evanghelii și i-a spus să aleagă pe care dintre cele două o voiește. Și fără șovăire el și-a întins mâna dreaptă și a luat dumnezeiasca Scriptură. „Ține-te, deci”, i-a zis Teotecn, „ține-te de Dumnezeu și, întărit de El, să dobândești ce ai ales și mergi în pace.”"},{"v":5,"t":"Îndată după întoarcerea lui, crainicul a strigat, chemându-l la tribunal, căci timpul rânduit se împlinise deja. Și stând înaintea tribunalului și arătând o râvnă și mai mare pentru credință, a fost dus îndată, așa cum era, și și-a încheiat cursa prin moarte."}];
window.LIB_LAZY["eusebiu-istoria#201"]=[{"v":1,"t":"Este pomenit și Astiriu pentru îndrăzneala lui cucernică în legătură cu această întâmplare. Era roman de rang senatorial, în bunăvoința împăraților și binecunoscut tuturor pentru nobila lui obârșie și avere. Fiind de față la moartea martirului, i-a luat trupul pe umăr și, îmbrăcându-l într-o haină strălucită și scumpă, l-a pregătit pentru mormânt în chip măreț și i-a dat o îngropare cuvenită. Prietenii acestui om, care mai trăiesc până în zilele noastre, povestesc multe alte fapte despre el."}];
window.LIB_LAZY["eusebiu-istoria#202"]=[{"v":1,"t":"Printre acestea este și următoarea minune. La Cezareea lui Filip, pe care fenicienii o numesc Paneas, se arată izvoare la poalele muntelui Paniu, din care curge Iordanul. Se spune că într-o anumită zi de sărbătoare a fost aruncată acolo o jertfă și că, prin puterea demonului, a dispărut în chip uimitor, iar ce s-a întâmplat a fost o minune vestită pentru cei de față. Astiriu a fost odată acolo când se făceau aceste lucruri și, văzând mulțimea uimită de întâmplare, i-a fost milă de rătăcirea lor; și, privind spre cer, s-a rugat Dumnezeului de peste toate, prin Hristos, să mustre pe demonul care amăgea poporul și să pună capăt amăgirii oamenilor. Și se spune că după ce s-a rugat astfel, îndată jertfa a plutit la suprafața izvorului. Și astfel minunea a plecat; și nicio minune nu s-a mai săvârșit vreodată în acel loc."}];
window.LIB_LAZY["eusebiu-istoria#203"]=[{"v":1,"t":"Fiindcă am pomenit această cetate, nu socot potrivit să las deoparte o povestire vrednică de a fi înregistrată pentru urmași. Căci se spune că femeia cu scurgere de sânge, care, după cum aflăm din sfânta Evanghelie, a primit de la Mântuitorul nostru izbăvire de suferința ei, era din acest loc și că i se arată casa în cetate și că acolo rămân amintiri remarcabile ale bunătății Mântuitorului față de ea."},{"v":2,"t":"Căci stă pe o piatră înălțată, lângă porțile casei ei, un chip de aramă al unei femei îngenunchiate, cu mâinile întinse, ca și cum s-ar ruga. În fața lui este un alt chip, drept, al unui bărbat, făcut din același material, îmbrăcat cuviincios într-o manta dublă și întinzând mâna spre femeie. La picioarele lui, lângă statuie, este o plantă ciudată, care se urcă până la poala mantalei de aramă și este leac pentru tot felul de boli."},{"v":3,"t":"Se spune că această statuie este chipul lui Isus. A rămas până în ziua de azi, așa încât și noi înșine am văzut-o când am locuit în cetate."},{"v":4,"t":"Și nu este de mirare că cei dintre neamuri care odinioară au fost binefăcuți de Mântuitorul nostru au făcut asemenea lucruri, de vreme ce am aflat că și chipurile apostolilor Săi Pavel și Petru și ale lui Hristos însuși se păstrează în picturi, cei din vechime având obiceiul, cum e probabil, după o deprindere a neamurilor, de a da acest fel de cinste, fără deosebire, celor socotiți de ei izbăvitori."}];
window.LIB_LAZY["eusebiu-istoria#204"]=[{"v":1,"t":"Scaunul lui Iacov, care a primit cel dintâi episcopia bisericii din Ierusalim de la Mântuitorul însuși și de la apostoli și care, după cum arată dumnezeieștile însemnări, a fost numit frate al lui Hristos, s-a păstrat până acum, frații care i-au urmat acolo în succesiune arătând limpede tuturor evlavia pe care cei din vechime, ca și cei din zilele noastre, au păstrat-o și o păstrează față de oamenii sfinți din pricina cucerniciei lor. Atât în privința acestui lucru."}];
window.LIB_LAZY["eusebiu-istoria#205"]=[{"v":1,"t":"Dionisie, pe lângă epistolele pomenite, a scris în acel timp și Epistolele sale pascale păstrate, în care folosește cuvinte de laudă despre sărbătoarea Paștilor. Pe una a adresat-o lui Flaviu, iar pe alta lui Domițiu și Didim, în care înfățișează un canon de opt ani, susținând că nu este potrivit să se țină sărbătoarea pascală decât după echinocțiul de primăvară. Pe lângă acestea a trimis o altă epistolă împreună-prezbiterilor săi din Alexandria, precum și diferite altele către diferite persoane, în timp ce prigoana încă bântuia."}];
window.LIB_LAZY["eusebiu-istoria#206"]=[{"v":1,"t":"Pacea fusese de-abia restabilită când s-a întors la Alexandria; dar izbucnind din nou răscoală și război, făcând cu neputință să vegheze asupra tuturor fraților, despărțiți în locuri diferite de răzmeriță, la sărbătoarea Paștilor, ca și cum ar fi fost încă exilat din Alexandria, li s-a adresat din nou prin scrisoare."},{"v":2,"t":"Și într-o altă epistolă pascală scrisă mai târziu lui Hierax, un episcop din Egipt, pomenește răscoala care bântuia atunci în Alexandria, astfel: Ce este de mirare că îmi este greu să țin legătura prin scrisori cu cei care locuiesc departe, când nu este în puterea mea nici măcar să judec cu mine însumi sau să mă sfătuiesc pentru propria mea viață?"},{"v":3,"t":"Într-adevăr, am nevoie să trimit scrisori celor care sunt ca propriile mele măruntaie, locuind într-o singură casă și frați dintr-un singur suflet și cetățeni ai aceleiași biserici; dar cum să le trimit nu pot spune. Căci ar fi mai ușor să meargă cineva nu numai dincolo de hotarele provinciei, ci chiar din Răsărit în Apus, decât din Alexandria până în Alexandria însăși."},{"v":4,"t":"Căci însăși inima cetății este mai încâlcită și mai de netrecut decât acel mare pustiu fără cărări pe care l-a străbătut Israel două generații. Iar porturile noastre netede și fără valuri au devenit ca marea, împărțite și zidite, prin care a trecut Israel și în a cărei cale au fost înecați egiptenii. Căci adesea, din măcelurile săvârșite acolo, par ca Marea Roșie."},{"v":5,"t":"Iar râul care curge pe lângă cetate a părut uneori mai uscat decât pustiul fără apă și mai arid decât acela în care Israel, trecând prin el, a suferit atât de mult de sete încât a strigat împotriva lui Moise și i-a curs apă din stânca abruptă, prin Cel ce singur face minuni."},{"v":6,"t":"Iarăși s-a revărsat atât de mult încât a inundat toată țara dimprejur, și drumurile, și câmpurile; amenințând să aducă înapoi potopul de ape din zilele lui Noe. Și curge mereu spurcat de sânge și măcel și înecări, cum a devenit pentru Faraon prin lucrarea lui Moise, când l-a schimbat în sânge și a duhnit."},{"v":7,"t":"Și ce altă apă ar putea curăța apa care curăță totul? Cum ar putea oceanul, atât de mare și de netrecut pentru oameni, vărsat în ea, să curețe această mare amară? Sau cum ar putea marele râu care ieșea din Eden, dacă ar vărsa cele patru capete în care se împarte în cel al Ghihonului, să spele această spurcăciune?"},{"v":8,"t":"Sau când se poate curăți aerul otrăvit de aceste miasme vătămătoare? Căci asemenea aburi se ridică din pământ, și vânturi din mare, și adieri din râu, și ceață din porturi, încât rourile sunt, ca să zic așa, scurgeri din trupuri moarte care putrezesc în toate elementele din jurul nostru."},{"v":9,"t":"Totuși oamenii se miră și nu pot înțelege de unde aceste ciume neîncetate; de unde aceste boli grele; de unde aceste boli de moarte de tot felul; de unde această variată și vastă nimicire omenească; de ce această mare cetate nu mai cuprinde atâția locuitori, de la pruncii fragezi până la cei mai înaintați în viață, câți cuprindea odinioară numai din cei pe care îi numea bătrâni zdraveni. Dar bărbații între patruzeci și șaptezeci de ani erau atunci atât de mulți încât numărul lor nu poate fi acum completat, nici măcar dacă se înscriu și se trec în registru, pentru rația publică de hrană, cei de la paisprezece până la optzeci de ani."},{"v":10,"t":"Iar cei mai tineri la înfățișare au devenit, ca să zic așa, de aceeași vârstă cu cei care erau odinioară cei mai bătrâni. Dar deși văd neamul omenesc micșorându-se și topindu-se astfel necontenit, și deși nimicirea lui deplină crește și înaintează, ei nu se cutremură."}];
window.LIB_LAZY["eusebiu-istoria#207"]=[{"v":1,"t":"După aceste întâmplări, o boală ciumată a urmat războiului și, la apropierea sărbătorii, a scris din nou fraților, descriind suferințele ce urmau acestei nenorociri."},{"v":2,"t":"Altor oameni timpul de față nu li s-ar părea potrivit pentru o sărbătoare. Dar nici acesta, nici alt timp nu este potrivit pentru ei; nici timpurile triste, nici măcar cele socotite deosebit de vesele. Acum, într-adevăr, totul este lacrimi și fiecare jelește, și tânguiri răsună zilnic prin cetate din pricina mulțimii morților și a celor care mor."},{"v":3,"t":"Căci, după cum s-a scris despre întâii-născuți ai egiptenilor, tot așa acum «s-a ridicat un mare strigăt, căci nu este casă în care să nu fie un mort.» (Exod 12:30) Și de-ar fi numai atât!"},{"v":4,"t":"Căci multe lucruri cumplite s-au întâmplat deja. Întâi ne-au izgonit; și pe când eram singuri și prigoniți și omorâți de toți, chiar și atunci am ținut sărbătoarea. Și orice loc de suferință era pentru noi loc de sărbătoare: câmp, pustiu, corabie, han, temniță; dar martirii desăvârșiți au ținut cea mai voioasă sărbătoare dintre toate, ospătându-se în cer."},{"v":5,"t":"După acestea au urmat război și foamete, pe care le-am îndurat împreună cu păgânii. Dar noi am purtat singuri cele cu care ne-au necăjit ei și, totodată, am simțit și urmările a ceea ce și-au făcut și au suferit ei unii de la alții; și, iarăși, ne-am bucurat de pacea lui Hristos, pe care ne-a dat-o numai nouă."},{"v":6,"t":"„Dar după ce atât noi, cât și ei ne-am bucurat de un timp foarte scurt de odihnă, această ciumă ne-a lovit; pentru ei mai îngrozitoare decât orice groază și mai de nesuferit decât orice altă nenorocire și, cum a spus unul dintre scriitorii lor, singurul lucru care biruie orice nădejde. Dar pentru noi nu a fost așa, ci a fost, nu mai puțin decât celelalte, o deprindere și o încercare. Căci nu s-a ținut departe nici de noi, dar pe păgâni i-a lovit mai aspru.”"},{"v":7,"t":"Mai departe adaugă: Cei mai mulți dintre frații noștri nu s-au cruțat, în prisosul dragostei și bunătății lor frățești. Se țineau strâns unii de alții și vizitau bolnavii fără teamă și le slujeau neîncetat, slujindu-le în Hristos. Și mureau cu ei cu mare bucurie, luând suferința altora și trăgând boala aproapelui asupra lor și primind de bunăvoie durerile lor. Și mulți dintre cei care au îngrijit de bolnavi și au dat putere altora au murit ei înșiși, mutând asupra lor moartea. Și zicerea populară, care pare totdeauna o simplă expresie de politețe, au făcut-o atunci faptă, plecând ca «gunoiul» altora."},{"v":8,"t":"Într-adevăr, cei mai buni dintre frații noștri au plecat din viață în acest chip, între ei unii prezbiteri și diaconi și dintre popor cei cu cea mai înaltă reputație; așa încât acest fel de moarte, prin marea cucernicie și credința tare pe care a arătat-o, părea că nu lipsește cu nimic de la martiriu."},{"v":9,"t":"Și luau trupurile sfinților în mâinile lor deschise și la piept și le închideau ochii și gura; și le purtau pe umeri și le așezau; și se lipeau de ele și le îmbrățișau; și le pregăteau cuviincios cu spălări și veșminte. Și după puțin primeau ei înșiși același tratament, căci supraviețuitorii îi urmau necontenit pe cei care mergeau înaintea lor."},{"v":10,"t":"„Dar cu păgânii totul era cu totul altfel. Îi părăseau pe cei care începeau să se îmbolnăvească și fugeau de cei mai dragi prieteni ai lor. Și îi aruncau pe străzi pe jumătate morți și lăsau morții ca gunoiul, neîngropați. Se feresc de orice părtășie și comuniune cu moartea; de care totuși, cu toate precauțiile lor, nu le era ușor să scape.”"},{"v":11,"t":"După această epistolă, când pacea fusese restabilită în cetate, a scris o altă scrisoare pascală frațiilor din Egipt și iarăși mai multe altele pe lângă aceasta. Și se păstrează și una Despre Sabat și alta Despre exercițiu."},{"v":12,"t":"Mai mult, a scris din nou o epistolă lui Hermammon și frăției din Egipt, descriind pe larg răutatea lui Deciu și a urmașilor lui și pomenind pacea sub Galien."}];
window.LIB_LAZY["eusebiu-istoria#208"]=[{"v":1,"t":"Dar nimic nu se compară cu a auzi propriile lui cuvinte, care sunt acestea: Atunci el, după ce a trădat pe unul dintre împărații care l-au precedat și a făcut război celuilalt, a pierit cu toată familia lui repede și cu desăvârșire. Dar Galien a fost proclamat și recunoscut de toți deodată ca împărat vechi și nou, fiind înaintea lor și rămânând după ei."},{"v":2,"t":"Căci după cuvântul rostit de proorocul Isaia: «Iată, cele de la început s-au împlinit și lucruri noi vor răsări acum.» (Isaia 42:9) Căci precum un nor trecând peste razele soarelui și întunecându-le pentru puțin timp îl ascunde și apare în locul lui; dar când norul a trecut sau s-a risipit, soarele care răsărise mai înainte apare din nou; așa Macrian, care s-a pus înainte și s-a apropiat de imperiul existent al lui Galien, nu mai este, de vreme ce nu a fost niciodată. Dar celălalt este tocmai cum a fost."},{"v":3,"t":"Iar împărăția lui, ca și cum ar fi lepădat bătrânețea și ar fi fost curățită de răutatea de mai înainte, înflorește acum mai viguros și este văzută și auzită mai departe și se întinde în toate direcțiile."},{"v":4,"t":"Apoi arată vremea în care a scris aceasta, în cuvintele următoare: „Îmi vine din nou în minte să trec în revistă zilele anilor împărătești. Căci văd că acei oameni prea nelegiuiți, deși au fost vestiți, au devenit totuși fără nume într-un timp scurt. Dar domnitorul mai sfânt și mai cucernic, după ce a trecut al șaptelea an, îl împlinește acum pe al nouălea, în care vom ține sărbătoarea.”"}];
window.LIB_LAZY["eusebiu-istoria#209"]=[{"v":1,"t":"Pe lângă toate acestea, a pregătit cele două cărți Despre făgăduințe. Prilejul lor a fost Nepos, un episcop din Egipt, care învăța că făgăduințele date oamenilor sfinți în dumnezeieștile Scripturi trebuie înțelese într-un chip mai iudaic și că va fi un anumit mileniu de desfătare trupească pe acest pământ."},{"v":2,"t":"Socotind că își poate întemeia părerea privată pe Apocalipsa lui Ioan, a scris o carte pe această temă, intitulată Combaterea alegoriștilor."},{"v":3,"t":"Dionisie i se împotrivește în cărțile sale Despre făgăduințe. În prima își dă propria părere despre dogmă; iar în a doua tratează despre Apocalipsa lui Ioan și, pomenindu-l pe Nepos la început, scrie despre el în acest chip:"},{"v":4,"t":"Dar fiindcă aduc înainte o anumită lucrare a lui Nepos, pe care se sprijină cu încredere, ca și cum ar dovedi fără îndoială că va fi o domnie a lui Hristos pe pământ, mărturisesc că în multe alte privințe îl aprob și îl iubesc pe Nepos, pentru credința, osârdia și sârguința lui în Scripturi și pentru bogata lui psalmodie, de care sunt încântați încă mulți dintre frați; și îl țin în cinste cu atât mai mult cu cât s-a dus la odihnă înaintea noastră. Dar adevărul trebuie iubit și cinstit mai presus de toate. Și în timp ce trebuie să lăudăm și să aprobăm fără zgârcenie ce se spune drept, trebuie să cercetăm și să îndreptăm ce nu pare scris sănătos."},{"v":5,"t":"Dacă ar fi de față să-și spună părerea oral, ar fi de ajuns o simplă discuție nescrisă, convingând și împăcând pe cei împotriviți prin întrebare și răspuns. Dar fiindcă unii socotesc lucrarea lui foarte plauzibilă și fiindcă anumiți învățători socotesc Legea și proorocii fără însemnătate și nu urmează Evangheliile și iau ușor epistolele apostolice, în timp ce fac făgăduințe în privința învățăturii acestei lucrări ca și cum ar fi vreo mare taină ascunsă și nu îngăduie frațiilor noștri mai simpli să aibă gânduri înalte și măreațe despre slăvita și cu adevărat dumnezeiasca arătare a Domnului nostru și despre învierea noastră din morți și despre adunarea noastră la El și asemănarea noastră cu El, ci dimpotrivă îi duc să nădăjduiască lucruri mici și muritoare în Împărăția lui Dumnezeu și lucruri precum cele de acum — fiind așa, este necesar să ne certăm cu fratele nostru Nepos ca și cum ar fi de față. Mai departe spune:"},{"v":6,"t":"Când eram în ținutul Arsinoe, unde, după cum știți, această învățătură a stăpânit de multă vreme, așa încât au rezultat schisme și apostazii ale unor biserici întregi, am chemat laolaltă pe prezbiterii și învățătorii frațiilor din sate — fiind de față și frații care au voit — și i-am îndemnat să facă o cercetare publică a acestei chestiuni."},{"v":7,"t":"Astfel, când mi-au adus această carte, ca pe o armă și o fortăreață de neînvins, stând cu ei de dimineață până seara trei zile la rând, m-am silit să îndrept ce era scris în ea."},{"v":8,"t":"Și m-am bucurat de statornicia, sinceritatea, docilitatea și inteligența frațiilor, pe când luam în considerare, în ordine și cu cumpătare, întrebările și greutățile și punctele de acord. Și ne-am ferit să apărăm în orice chip și cu încăpățânare părerile pe care le avusesem odată, dacă nu păreau corecte. Nici nu am ocolit obiecțiile, ci ne-am străduit pe cât s-a putut să ținem și să întărim lucrurile care erau înaintea noastră, și dacă motivul dat ne mulțumea, nu ne era rușine să ne schimbăm părerile și să ne învoim cu alții; ci, dimpotrivă, cu conștiință și sinceritate și cu inimile deschise înaintea lui Dumnezeu, am primit tot ce era întemeiat prin dovezile și învățăturile Sfintelor Scripturi."},{"v":9,"t":"Și în cele din urmă, autorul și stârnitorul acestei învățături, care se numea Corakion, în auzul tuturor fraților care erau de față, a recunoscut și ne-a mărturisit că nu va mai ține această părere, nici nu o va dezbate, nici nu o va pomeni, nici nu o va învăța, fiind pe deplin convins de argumentele împotriva ei. Iar unii dintre ceilalți frați și-au exprimat mulțumirea față de întâlnire și față de duhul de împăcare și armonie pe care toți îl arătaseră."}];
window.LIB_LAZY["eusebiu-istoria#210"]=[{"v":1,"t":"După aceea vorbește în acest chip despre Apocalipsa lui Ioan. Unii dinaintea noastră au dat deoparte și au respins cartea cu totul, criticând-o capitol cu capitol și declarând-o fără sens și fără argument și susținând că titlul este fals."},{"v":2,"t":"Căci spun că nu este lucrarea lui Ioan și nici nu este o descoperire, pentru că este acoperită des și gros de un văl de neînțeles. Și afirmă că niciunul dintre apostoli, niciunul dintre sfinți, nici vreunul din Biserică nu este autorul ei, ci că Cherint, care a întemeiat secta numită după el cherintiană, dorind o autoritate respectabilă pentru născocirea lui, i-a pus în față acest nume."},{"v":3,"t":"Căci învățătura pe care o dădea era aceasta: că împărăția lui Hristos va fi pământească. Și fiind el însuși dedicat plăcerilor trupului și cu totul senzual din fire, a visat că acea împărăție va consta în lucrurile pe care le dorea, anume în desfătările pântecelui și ale pasiunii sexuale; adică în mâncare și băutură și căsătorie, și în sărbători și jertfe și înjunghierea de animale, sub înfățișarea cărora credea că își poate satisface poftele cu mai bună cuviință."},{"v":4,"t":"Dar eu nu am putut cuteza să resping cartea, căci mulți frați o țin în mare cinste. Dar presupun că este dincolo de înțelegerea mea și că în fiecare parte este un înțeles ascuns și mai minunat. Căci dacă nu înțeleg, bănuiesc că un sens mai adânc se află sub cuvinte."},{"v":5,"t":"Nu le măsor și nu le judec cu propria mea rațiune, ci, lăsând mai mult credinței, le socotesc prea înalte pentru ca eu să le cuprind. Și nu resping ce nu pot înțelege, ci mă minunez mai degrabă pentru că nu înțeleg."},{"v":6,"t":"După aceasta cercetează întreaga carte a Apocalipsei și, după ce a dovedit că este cu neputință să fie înțeleasă după sensul literal, merge mai departe astfel: Încheind toată proorocia, ca să zic așa, proorocul îi declară fericiți pe cei care o vor păzi și pe sine însuși. Căci spune: «Fericit este cel ce păzește cuvintele proorociei acestei cărți, și eu, Ioan, cel ce am văzut și am auzit aceste lucruri.»"},{"v":7,"t":"Deci că se numea Ioan și că această carte este lucrarea unui Ioan, nu tăgăduiesc. Și mă învoiesc de asemenea că este lucrarea unui om sfânt și insuflat. Dar nu pot admite lesne că a fost apostolul, fiul lui Zebedei, fratele lui Iacov, prin care au fost scrise Evanghelia lui Ioan și Epistola catolică."},{"v":8,"t":"Căci judec din caracterul amândurora, din felurile de exprimare și din întreaga alcătuire a cărții, că nu este a lui. Căci evanghelistul nu-și dă nicăieri numele, nici nu se vestește pe sine, nici în Evanghelie, nici în Epistolă."},{"v":9,"t":"Mai departe adaugă: Dar Ioan nu vorbește niciodată ca și cum s-ar referi la sine sau ca și cum s-ar referi la altă persoană. Dar autorul Apocalipsei se înfățișează chiar de la început: «Descoperirea lui Isus Hristos, pe care i-a dat-o Dumnezeu ca să arate robilor Săi în curând; și a trimis-o și a făcut-o cunoscută prin îngerul Său robului Său Ioan, care a mărturisit cuvântul lui Dumnezeu și mărturia lui Isus Hristos, tot ce a văzut.» (Apocalipsa 1:1-2)"},{"v":10,"t":"Apoi scrie și o epistolă: «Ioan, celor șapte biserici care sunt în Asia: har vouă și pace.» (Apocalipsa 1:4) Dar evanghelistul nu și-a pus numele nici în Epistola catolică; ci fără introducere începe cu însăși taina dumnezeieștii descoperiri: «Ce era de la început, ce am auzit, ce am văzut cu ochii noștri.» (1 Ioan 1:1) Căci pentru o asemenea descoperire Domnul l-a fericit și pe Petru, zicând: «Fericit ești, Simone, fiul lui Iona, căci nu carnea și sângele ți-au descoperit aceasta, ci Tatăl Meu cel din ceruri.» (Matei 16:17)"},{"v":11,"t":"Dar nici în așa-numita a doua sau a treia epistolă a lui Ioan, deși sunt foarte scurte, nu apare numele Ioan; ci este scrisă expresia anonimă «prezbiterul». Dar acest autor nu a socotit de ajuns să-și dea numele o dată și să meargă mai departe cu lucrarea; ci îl reia: «Eu, Ioan, fratele vostru și părtaș cu voi la necaz și la împărăție și la răbdarea în Isus Hristos, am fost în insula numită Patmos, pentru cuvântul lui Dumnezeu și mărturia lui Isus.» (Apocalipsa 1:9) Și spre încheiere vorbește astfel: «Fericit este cel ce păzește cuvintele proorociei acestei cărți, și eu, Ioan, cel ce am văzut și am auzit aceste lucruri.»"},{"v":12,"t":"Dar că cel care a scris acestea se numea Ioan trebuie crezut, de vreme ce o spune; dar cine era nu se vede. Căci nu a spus, ca adesea în Evanghelie, că era ucenicul iubit al Domnului, sau cel care s-a rezemat pe pieptul Lui, sau fratele lui Iacov, sau martorul ocular și ascultătorul Domnului."},{"v":13,"t":"Căci ar fi vorbit de acestea dacă ar fi voit să se arate limpede. Dar nu spune niciuna dintre ele; ci vorbește despre sine ca despre fratele și părtașul nostru și martor al lui Isus și fericit pentru că văzuse și auzise descoperirile."},{"v":14,"t":"Dar sunt de părere că mulți au avut același nume ca apostolul Ioan, care, din dragostea față de el și pentru că îl admirau și îl urmau și doreau să fie iubiți de Domnul ca el, și-au luat același nume, după cum mulți dintre copiii credincioșilor se numesc Pavel sau Petru."},{"v":15,"t":"De pildă, mai este și un alt Ioan, supranumit Marcu, pomenit în Faptele Apostolilor, pe care Barnaba și Pavel l-au luat cu ei; despre care se spune: «Și aveau și pe Ioan ca ajutor.» (Fapte 13:5) Dar că el este cel care a scris aceasta, nu aș spune. Căci nu este scris că a mers cu ei în Asia, ci: «Pavel și tovarășii lui, plecând cu corabia din Pafos, au venit la Perga Pamfiliei; dar Ioan, despărțindu-se de ei, s-a întors la Ierusalim.» (Fapte 13:13)"},{"v":16,"t":"Dar socotesc că era vreun altul dintre cei din Asia; căci se spune că sunt două morminte în Efes, fiecare purtând numele Ioan."},{"v":17,"t":"Și din idei, din cuvinte și din așezarea lor se poate presupune cu temei că acesta este deosebit de acela."},{"v":18,"t":"Căci Evanghelia și Epistola se potrivesc una cu alta și încep în același fel. Una spune: «La început era Cuvântul» (Ioan 1:1); cealaltă: «Ce era de la început». (1 Ioan 1:1) Una: «Și Cuvântul S-a făcut trup și a locuit între noi și am văzut slava Lui, slavă ca a Unuia-Născut din Tatăl»; (Ioan 1:14) cealaltă spune aceleași lucruri ușor schimbate: «Ce am auzit, ce am văzut cu ochii noștri; ce am privit și mâinile noastre au pipăit despre Cuvântul vieții — și viața s-a arătat.» (1 Ioan 1:1-2)"},{"v":19,"t":"Căci le introduce la început, susținându-le, după cum este vădit din ce urmează, împotriva celor care ziceau că Domnul nu a venit în trup. De aceea adaugă cu grijă: «Și am văzut și mărturisim și vă vestim viața veșnică, care era la Tatăl și ni s-a arătat nouă. Ce am văzut și am auzit vă vestim și vouă.» (1 Ioan 1:2-3)"},{"v":20,"t":"Se ține de aceasta și nu se abate de la subiectul său, ci discută totul sub aceleași capete și numește unele pe care le vom pomeni pe scurt."},{"v":21,"t":"Oricine cercetează cu grijă va găsi expresiile «viața», «lumina», «întoarcerea de la întuneric», des repetate în amândouă; de asemenea necontenit «adevărul», «harul», «bucuria», «trupul și sângele Domnului», «judecata», «iertarea păcatelor», «dragostea lui Dumnezeu față de noi», «porunca de a ne iubi unii pe alții», de a «păzi toate poruncile»; «mustrarea lumii, a Diavolului, a lui Antihrist», «făgăduința Duhului Sfânt», «înfierea de la Dumnezeu», «credința cerută necontenit de la noi», «Tatăl și Fiul» se găsesc pretutindeni. De fapt, se vede limpede că același caracter marchează Evanghelia și Epistola de la un capăt la altul."},{"v":22,"t":"Dar Apocalipsa este deosebită de aceste scrieri și străină lor; neatingându-le, nici hotărnicindu-se câtuși de puțin cu ele; aproape, ca să zic așa, fără nici măcar o silabă comună cu ele."},{"v":23,"t":"Ba mai mult, Epistola — căci las deoparte Evanghelia — nu pomenește și nu cuprinde nicio aluzie la Apocalipsă, nici Apocalipsa la Epistolă. Dar Pavel, în epistolele sale, dă o oarecare indicație a descoperirilor sale, deși nu le-a scris separat."},{"v":24,"t":"Mai mult, se poate arăta de asemenea că dicțiunea Evangheliei și a Epistolei diferă de a Apocalipsei."},{"v":25,"t":"Căci acelea au fost scrise nu numai fără greșeală în privința limbii grecești, ci și cu eleganță în exprimare, în raționamente și în întreaga structură. Sunt, într-adevăr, departe de a trăda vreun barbarism sau solecism sau vreun vulgarism oarecare. Căci scriitorul avea, după cum se pare, ambele cerințe ale cuvântării — adică darul cunoașterii și darul exprimării — Domnul acordându-i-le pe amândouă."},{"v":26,"t":"Nu tăgăduiesc că celălalt scriitor a văzut o descoperire și a primit cunoaștere și proorocie. Observ însă că dialectul și limba lui nu sunt greacă exactă, ci că folosește expresii barbare și, în unele locuri, solecisme."},{"v":27,"t":"Nu este nevoie să le arăt aici, căci nu aș vrea ca cineva să creadă că am spus aceste lucruri în spirit de batjocură, ci am spus ce am spus doar cu scopul de a arăta limpede deosebirea dintre scrieri."}];
window.LIB_LAZY["eusebiu-istoria#211"]=[{"v":1,"t":"Pe lângă acestea, se păstrează multe alte epistole ale lui Dionisie, precum cele împotriva lui Sabeliu, adresate lui Ammon, episcopul bisericii din Berenice, una către Telesfor, una către Eufranor și iarăși alta către Ammon și Euporus. A scris și alte patru cărți pe aceeași temă, pe care le-a adresat omonimului său Dionisie din Roma."},{"v":2,"t":"Pe lângă acestea avem multe dintre epistolele lui și cărți mari scrise în formă epistolară, precum cele Despre natură, adresate tânărului Timotei, și una Despre ispite, pe care a închinat-o tot lui Eufranor."},{"v":3,"t":"Mai mult, într-o scrisoare către Vasilide, episcopul parohiilor din Pentapole, spune că a scris o expunere a începutului Eclesiastului. Și ne-a lăsat și diferite scrisori adresate aceleiași persoane. Atât despre Dionisie. Dar încheindu-se relatarea noastră despre aceste chestiuni, îngăduiți-ne să arătăm urmașilor chipul vremii noastre."}];
window.LIB_LAZY["eusebiu-istoria#212"]=[{"v":1,"t":"După ce Xyst păstorise biserica Romei unsprezece ani, i-a urmat Dionisie, omonimul celui din Alexandria. Cam în același timp a murit Demetrian în Antiohia și Pavel din Samosata a primit acea episcopie."},{"v":2,"t":"Fiindcă ținea, împotriva învățăturii Bisericii, păreri josnice și degradate despre Hristos, anume că în firea Lui era un om de rând, Dionisie al Alexandriei a fost rugat să vină la sinod. Dar neputând veni din pricina vârstei și a slăbiciunii trupești, și-a dat părerea asupra chestiunii în discuție prin scrisoare. Dar toți ceilalți păstori ai bisericilor din toate părțile s-au grăbit să se adune la Antiohia, ca împotriva unui jefuitor al turmei lui Hristos."}];
window.LIB_LAZY["eusebiu-istoria#213"]=[{"v":1,"t":"Dintre aceștia, cei mai de seamă au fost Firmilian, episcopul Cezareei Capadociei; frații Grigorie și Atenodor, păstorii bisericilor din Pont; Helen al parohiei Tarsului și Nicoma din Iconiu; de asemenea Imeneu, al bisericii din Ierusalim, și Teotecn al bisericii vecine a Cezareei; și pe lângă aceștia Maxim, care păstorea într-un chip deosebit frații din Bostra. Dacă i-ar număra cineva, nu ar putea să nu observe o mulțime de alții, pe lângă prezbiteri și diaconi, care se adunaseră atunci pentru aceeași pricină în cetatea pomenită. Dar aceștia erau cei mai însemnați."},{"v":2,"t":"Când toți aceștia s-au adunat la diferite timpuri și adesea ca să cerceteze aceste lucruri, la fiecare întrunire au fost dezbătute argumentele și întrebările; adepții samosateanului străduindu-se să acopere și să ascundă erezia lui, iar ceilalți străduindu-se cu râvnă să dezvăluie și să arate limpede erezia și hula lui împotriva lui Hristos."},{"v":3,"t":"Între timp, Dionisie a murit în al doisprezecelea an al domniei lui Galien, după ce ținuse episcopia Alexandriei șaptesprezece ani, și Maxim i-a urmat."},{"v":4,"t":"După o domnie de cincisprezece ani, lui Galien i-a urmat Claudiu, care în doi ani a predat stăpânirea lui Aurelian."}];
window.LIB_LAZY["eusebiu-istoria#214"]=[{"v":1,"t":"În domnia lui s-a ținut un sinod din urmă, alcătuit dintr-o mulțime de episcopi, iar căpetenia ereziei din Antiohia a fost descoperită și învățătura lui mincinoasă arătată limpede înaintea tuturor și a fost excomunicat din Biserica Catolică de sub cer."},{"v":2,"t":"Malhion, mai ales, l-a scos din ascunzătoare și l-a combătut. Era un om învățat și în alte privințe și conducătorul școlii sofiștilor de învățătură grecească din Antiohia; totuși, din pricina nobleței mai înalte a credinței sale în Hristos, fusese făcut prezbiter al acelei parohii. Acest om, purtând o discuție cu el, care a fost luată de stenografi și despre care știm că se păstrează încă, a fost singurul în stare să-l descopere pe omul care se prefăcea și înșela pe ceilalți."}];
window.LIB_LAZY["eusebiu-istoria#215"]=[{"v":1,"t":"Păstorii care se adunaseră în această privință au pregătit, de comun acord, o epistolă adresată lui Dionisie, episcopul Romei, și lui Maxim al Alexandriei, și au trimis-o în toate provinciile. În ea fac cunoscută tuturor propria lor râvnă și rătăcirea răzvrătită a lui Pavel și argumentele și discuțiile pe care le-au avut cu el și arată întreaga viață și purtare a omului. Poate fi bine să consemnăm acum următoarele extrase din scrierea lor:"},{"v":2,"t":"„Lui Dionisie și Maxim și tuturor împreună-slujitorilor noștri din toată lumea, episcopi, prezbiteri și diaconi, și întregii Biserici Catolice de sub cer, Helen, Imeneu, Teofil, Teotecn, Maxim, Proclu, Nicoma, Eliân, Pavel, Bolan, Protogen, Hierax, Eutihie, Teodor, Malhion și Luciu și toți ceilalți care locuiesc împreună cu noi în cetățile și neamurile învecinate, episcopi, prezbiteri și diaconi, și bisericile lui Dumnezeu, salutare iubiților frați în Domnul.”"},{"v":3,"t":"Puțin mai departe merg astfel: Am trimis după mulți dintre episcopii de departe și i-am chemat să ne ușureze de această învățătură aducătoare de moarte; ca Dionisie al Alexandriei și Firmilian al Capadociei, acei oameni fericiți. Cel dintâi dintre ei, nesocotind pe autorul acestei amăgiri vrednic de a i se adresa, a trimis o scrisoare la Antiohia, nescrisă lui, ci întregii parohii, din care dăm mai jos o copie."},{"v":4,"t":"Dar Firmilian a venit de două ori și i-a condamnat noutățile, după cum știm și mărturisim noi, cei care am fost de față, și înțeleg mulți alții. Dar fiindcă a făgăduit să-și schimbe părerile, l-a crezut și a nădăjduit că, fără nicio ocară pentru Cuvânt, se va face ce era necesar. Așa că a amânat chestiunea, fiind înșelat de cel care a tăgăduit chiar pe propriul lui Dumnezeu și Domn și nu a păzit credința pe care o avusese mai înainte."},{"v":5,"t":"Și acum Firmilian era din nou pe drum spre Antiohia și ajunsese până la Tars, pentru că aflase din experiență răutatea lui lepădătoare de Dumnezeu. Dar pe când noi, adunați, îl chemam și îi așteptam sosirea, a murit."},{"v":6,"t":"După alte lucruri, descriu astfel felul de viață pe care l-a dus:"},{"v":7,"t":"Întrucât s-a depărtat de canonul credinței și s-a abătut după învățături josnice și false, nu este necesar — fiindcă este în afară — să dăm sentință asupra practicilor lui: de pildă, în aceea că deși mai înainte lipsit și sărac, și neprimind nicio avere de la părinții lui, nici câștigând ceva din meșteșug sau negoț, acum are bogății îmbelșugate prin nedreptățile și faptele lui sacrilege și prin cele pe care le stoarce de la frați, lipsind pe cei nedreptățiți de drepturile lor și făgăduindu-le ajutor pe plată, dar înșelându-i, și jefuind pe cei care, în necazul lor, sunt gata să dea ca să se împace cu asupritorii lor, «socotind că evlavia este un câștig»; (1 Timotei 6:5) —"},{"v":8,"t":"sau în aceea că este trufaș și îngâmfat și își însușește demnități lumești, preferând să fie numit ducenar mai degrabă decât episcop; și se pavoazează prin piețe, citind scrisori și recitându-le în timp ce merge în public, însoțit de o gardă de corp, cu o mulțime înaintea și în urma lui, așa încât credința este invidiată și urâtă din pricina mândriei și trufiei inimii lui —"},{"v":9,"t":"sau în aceea că practică șicane în adunările bisericești, se străduiește să se slăvească pe sine și să înșele cu aparențe și să uimească mințile celor simpli, pregătindu-și un tribunal și un scaun înalt — nu ca un ucenic al lui Hristos — și având un «secretum» — ca stăpânitorii lumii — și numindu-l astfel, și lovindu-și coapsa cu mâna și bătând din picioare pe tribunal — sau în aceea că mustră și insultă pe cei care nu aplaudă și nu flutură batistele ca în teatre și nu strigă și nu sar ca bărbații și femeile așezați în jurul lui, care îl ascultă în acest chip nepotrivit, ci ascultă cu evlavie și rânduială ca în casa lui Dumnezeu — sau în aceea că atacă în public cu violență și grosolănie pe tâlcuitorii Cuvântului care au plecat din această viață și se înalță pe sine nu ca episcop, ci ca sofist și scamator,"},{"v":10,"t":"și oprește psalmii către Domnul nostru Isus Hristos, ca fiind producții recente ale unor oameni recenți, și pregătește femei să cânte psalmi către el în mijlocul bisericii în marea zi a Paștilor, lucru de care s-ar înfiora oricine să audă, și convinge pe episcopii și prezbiterii din ținuturile și cetățile învecinate care îl lingușesc să înainteze aceleași idei în cuvântările lor către popor."},{"v":11,"t":"Căci, ca să anticipăm ceva din ce vom scrie îndată, nu vrea să recunoască că Fiul lui Dumnezeu s-a coborât din cer. Și aceasta nu este o simplă afirmație, ci este dovedită din belșug din însemnările pe care vi le-am trimis; și nu cel mai puțin acolo unde spune «Isus Hristos este de jos». Dar cei care îi cântă și îl laudă între popor spun că învățătorul lor nelegiuit s-a coborât înger din cer. Și el nu oprește asemenea lucruri; ci omul trufaș este chiar de față când se rostesc."},{"v":12,"t":"Și sunt femeile, «subintroductae», cum le numesc antiohienii, ale lui și ale prezbiterilor și diaconilor care sunt cu el. Deși îi cunoaște și i-a dovedit vinovați pe acești oameni, închide ochii la aceasta și la celelalte păcate ale lor fără leac, ca să fie legați de el și, de frică pentru ei înșiși, să nu cuteze să-l acuze pentru cuvintele și faptele lui rele. Dar i-a și îmbogățit; din care pricină este iubit și admirat de cei care râvnesc la asemenea lucruri."},{"v":13,"t":"Știm, iubiților, că episcopul și tot clerul trebuie să fie pildă poporului în toate lucrurile bune. Și nu ignorăm câți au căzut sau au atras bănuieli prin femeile pe care le-au adus astfel. Așa încât, chiar dacă am îngădui că el nu săvârșește niciun act păcătos, totuși ar trebui să ocolească bănuiala care se ridică dintr-un astfel de lucru, ca să nu sminteze pe cineva sau să-i ducă pe alții să-l imite."},{"v":14,"t":"Căci cum poate mustra sau sfătui pe altul să nu fie prea familiar cu femeile — ca să nu cadă, după cum este scris —, când el însuși a trimis deja pe una, iar acum are două cu el, în floare și frumoase, și le ia cu el oriunde merge, trăind totodată în desfătare și îmbuibare?"},{"v":15,"t":"Din pricina acestor lucruri toți se tânguiesc și jelesc între ei; dar se tem atât de mult de tirania și puterea lui, încât nu cutează să-l acuze."},{"v":16,"t":"Dar, după cum am spus, deși omul ar putea fi tras la răspundere pentru această purtare, dacă ar ține învățătura catolică și ar fi numărat cu noi, de vreme ce a disprețuit taina și se pavoazează în scârboasa erezie a lui Artemas (căci de ce să nu-i pomenim părintele?), socotim de prisos să-i cerem socoteală pentru aceste lucruri."},{"v":17,"t":"Mai târziu, la încheierea epistolei, adaugă aceste cuvinte: „De aceea am fost siliți să-l excomunicăm, de vreme ce se pune împotriva lui Dumnezeu și refuză să asculte, și să rânduim în locul lui un alt episcop pentru Biserica Catolică. Prin îndrumare dumnezeiască, după cum credem, l-am rânduit pe Domn, care este împodobit cu toate însușirile cuvenite unui episcop și care este fiul fericitului Demetrian, ce păstorise odinioară într-un chip deosebit aceeași parohie. V-am înștiințat aceasta ca să-i scrieți și să primiți de la el scrisori de împărtășire. Dar acest om să-i scrie lui Artemas; și cei care gândesc ca Artemas să se împărtășească cu el.”"},{"v":18,"t":"Pavel căzând din episcopie, ca și din credința ortodoxă, Domn, după cum s-a spus, a devenit episcop al bisericii din Antiohia."},{"v":19,"t":"Dar fiindcă Pavel refuza să predea clădirea bisericii, s-a adresat o petiție împăratului Aurelian; iar el a hotărât chestiunea cu foarte multă echitate, poruncind ca clădirea să fie dată celor cărora le-o vor judeca episcopii Italiei și ai cetății Romei. Astfel acest om a fost izgonit din biserică, cu extremă rușine, de puterea lumească."},{"v":20,"t":"Astfel a fost purtarea lui Aurelian față de noi în acel timp; dar în cursul domniei sale și-a schimbat gândul în privința noastră și a fost mișcat de unii sfetnici să pornească o prigoană împotriva noastră. Și se vorbea mult despre aceasta din toate părțile."},{"v":21,"t":"Dar pe când era gata să o facă și era, ca să zic așa, chiar în clipa semnării decretelor împotriva noastră, judecata dumnezeiască a venit peste el și l-a oprit chiar în pragul întreprinderii, arătând într-un chip pe care toți îl pot vedea limpede că stăpânitorii acestei lumi nu pot găsi niciodată prilej împotriva bisericilor lui Hristos, decât dacă mâna care le apără îngăduie aceasta, printr-o judecată dumnezeiască și cerească, spre disciplină și îndreptare, în vremurile pe care le vede cu cale."},{"v":22,"t":"După o domnie de șase ani, lui Aurelian i-a urmat Probus. A domnit același număr de ani și i-au urmat Car, cu fiii săi Carin și Numerian. După ce au domnit mai puțin de trei ani, stăpânirea a trecut la Dioclețian și cei asociați cu el. Sub ei s-a petrecut prigoana din vremea noastră și nimicirea bisericilor legată de ea."},{"v":23,"t":"Cu puțin înainte de aceasta, Dionisie, episcopul Romei, după ce ținuse slujba nouă ani, a murit și i-a urmat Felix."}];
window.LIB_LAZY["eusebiu-istoria#216"]=[{"v":1,"t":"În acest timp, nebunul, numit după erezia lui demonică, s-a înarmat în răstălmăcirea rațiunii sale, diavolul Satan, care luptă el însuși împotriva lui Dumnezeu, înfățișându-l spre pierzarea multora. Era un barbar în viață, atât în cuvânt, cât și în faptă; și în firea lui demonic și nebun. Din această pricină a căutat să se dea drept Hristos și, umflat în nebunia lui, s-a proclamat Mângâietorul și chiar Duhul Sfânt; și după aceea, ca Hristos, și-a ales doisprezece ucenici ca părtași ai noii lui învățături."},{"v":2,"t":"Și a cârpit laolaltă învățături false și fără Dumnezeu, adunate dintr-o mulțime de nelegiuiri de mult stinse, și le-a măturat, ca pe o otravă aducătoare de moarte, din Persia în partea noastră de lume. De la el numele nelegiuit al maniheilor este încă răspândit între mulți. Aceasta a fost temelia acestei «cunoștințe pe nedrept numite așa», care s-a ridicat în acele vremuri."}];
window.LIB_LAZY["eusebiu-istoria#217"]=[{"v":1,"t":"În acest timp, Felix, după ce păstorise biserica Romei cinci ani, a fost urmat de Eutihian, dar acesta, în mai puțin de zece luni, a lăsat slujba lui Gaiu, care a trăit în zilele noastre. El a ținut-o cam cincisprezece ani și i-a urmat, la rândul lui, Marcelin, care a fost ajuns de prigoană."},{"v":2,"t":"Cam în același timp Timeu a primit episcopia Antiohiei după Domn, și Chiril, care a trăit în zilele noastre, i-a urmat. În vremea lui l-am cunoscut pe Doroteu, un om învățat între cei din vremea lui, care a fost cinstit cu slujba de prezbiter în Antiohia. Era un iubitor al frumosului în cele dumnezeiești și s-a dedicat limbii evreiești, așa încât citea cu ușurință Scripturile evreiești."},{"v":3,"t":"Făcea parte dintre cei deosebit de liberali și nu era străin de pregătirea elementară grecească. Pe lângă aceasta era famen, fiind astfel chiar din nașterea lui. Din această pricină, ca și cum ar fi fost o minune, împăratul l-a luat în casa lui și l-a cinstit punându-l peste vopsitoriile de purpură din Tir. L-am auzit tâlcuind cu înțelepciune Scripturile în Biserică."},{"v":4,"t":"După Chiril, Tiran a primit episcopia parohiei Antiohiei. În vremea lui a avut loc nimicirea bisericilor."},{"v":5,"t":"Eusebiu, care venise din cetatea Alexandriei, a condus parohiile Laodiceei după Socrate. Prilejul mutării lui acolo a fost chestiunea lui Pavel. A mers din această pricină în Siria și a fost oprit să se întoarcă acasă de cei de acolo care erau râvnitori în cele dumnezeiești. Printre contemporanii noștri a fost o frumoasă pildă de religie, după cum se vede lesne din cuvintele lui Dionisie pe care le-am citat."},{"v":6,"t":"Anatolie a fost rânduit urmașul lui; un om bun urmând altuia, cum se spune. Și el era alexandrin de neam. În învățătură și pricepere în filozofia greacă, cum sunt aritmetica și geometria, astronomia și dialectica în general, precum și în teoria fizicii, stătea cel dintâi între cei mai pricepuți bărbați ai vremii noastre și era și în fruntea științei retorice. Se povestește că din această pricină cetățenii Alexandriei i-au cerut să întemeieze acolo o școală de filozofie aristotelică."},{"v":7,"t":"Povestesc despre el multe alte fapte însemnate din timpul asediului Pirucheionului din Alexandria, pentru care a fost deosebit de cinstit de toți cei aflați în funcții înalte; dar voi da numai următoarea ca exemplu."},{"v":8,"t":"Se spune că pâinea lipsise celor asediați, așa încât era mai greu să reziste foametei decât dușmanului de afară; dar el, fiind de față, a purtat grijă de ei în acest chip. Cum cealaltă parte a cetății era aliată cu armata romană și deci nu era asediată, Anatolie a trimis după Eusebiu — căci era încă acolo înainte de mutarea lui în Siria și se număra printre cei neasediați și avea, pe deasupra, o mare reputație și un nume vestit care ajunsese chiar până la generalul roman — și l-a înștiințat despre cei care piereau în asediu de foame."},{"v":9,"t":"Când a aflat aceasta, a cerut comandantului roman, ca cel mai mare favor cu putință, să acorde siguranță dezertorilor din tabăra dușmană. Obținând cererea, a comunicat-o lui Anatolie. De îndată ce a primit mesajul, acesta a convocat senatul Alexandriei și a propus mai întâi ca toți să vină la împăcare cu romanii. Dar când a văzut că se mâniaseră de acest sfat, a spus: „Dar nu cred că vă veți împotrivi mie, dacă vă sfătuiesc să trimiteți în afara porților pe cei de prisos și pe cei care nu ne sunt întru nimic de folos, ca bătrânele, copiii și bătrânii, să meargă oriunde vor voi. Căci de ce să-i păstrăm în zadar pe cei care oricum vor muri în curând? Și de ce să-i nimicim cu foamea pe cei schilodiți și ciungi în trup, când ar trebui să purtăm grijă doar de bărbați și tineri și să împărțim pâinea necesară între cei care sunt de trebuință pentru garnizoana cetății?”"},{"v":10,"t":"Cu asemenea argumente a convins adunarea și, ridicându-se cel dintâi, și-a dat votul ca toată mulțimea, fie bărbați, fie femei, care nu era de trebuință armatei, să plece din cetate, căci dacă ar rămâne și ar continua fără nevoie în cetate, nu ar avea nicio nădejde de scăpare, ci ar pieri de foame."},{"v":11,"t":"Cum toți ceilalți din senat s-au învoit la aceasta, i-a mântuit aproape pe toți cei asediați. A rânduit ca, mai întâi, cei care țineau de biserică și apoi, dintre ceilalți din cetate, cei de orice vârstă să scape, nu numai categoriile incluse în decret, ci, sub acoperirea acestora, o mulțime de alții, îmbrăcați pe ascuns în haine de femei; și prin chibzuința lui au ieșit pe porți noaptea și au scăpat în tabăra romană. Acolo Eusebiu, ca un părinte și doctor, i-a primit pe toți, istoviți de lungul asediu, și i-a refăcut prin tot felul de prevedere și grijă."},{"v":12,"t":"Biserica din Laodiceea a fost cinstită de doi asemenea păstori la rând, care, prin purtarea de grijă a lui Dumnezeu, au venit după războiul amintit din Alexandria în acea cetate."},{"v":13,"t":"Anatolie nu a scris foarte multe lucrări; dar în cele care au ajuns la noi putem deslușa elocvența și erudiția lui. În ele își arată mai ales părerile despre Paști. Pare important să dăm aici următoarele extrase din ele."},{"v":14,"t":"Din Canoanele pascale ale lui Anatolie. Este, deci, în primul an luna nouă a lunii întâi, care este începutul fiecărui ciclu de nouăsprezece ani, în ziua a douăzeci și șasea a lunii egiptene Famenot; dar după lunile macedonenilor, în ziua a douăzeci și doua a lui Distru, sau, cum ar spune romanii, a unsprezecea zi înainte de calendele lui aprilie."},{"v":15,"t":"În numita zi a douăzeci și șasea a lui Famenot, soarele se află nu numai intrat în prima secțiune, ci trecând deja prin a patra zi din ea. Obișnuiesc să numească această secțiune întâiul dodecatemorion, și echinocțiul, și începutul lunilor, și capul ciclului, și punctul de plecare al circuitului planetar. Dar pe cea dinaintea acesteia o numesc ultima a lunilor, și a douăsprezecea secțiune, și ultimul dodecatemorion, și sfârșitul circuitului planetar. De aceea susținem că cei care pun în ea luna întâi și hotărăsc după ea ziua a paisprezecea a Paștilor săvârșesc o greșeală nu mică sau obișnuită."},{"v":16,"t":"Și aceasta nu este o părere a noastră; ci era cunoscută iudeilor de demult, chiar înainte de Hristos, și păzită de ei cu grijă. Aceasta se poate afla din ce se spune de Filon, Josephus și Museu; și nu numai de ei, ci și de cei încă mai vechi, cei doi Agatobuli, supranumiți «Învățători», și vestitul Aristobul, care a fost ales între cei șaptezeci de tâlcuitori ai sfintelor și dumnezeieștilor Scripturi evreiești de Ptolemeu Filadelful și de tatăl său și care a închinat acelorași regi cărțile sale de tâlcuire a Legii lui Moise."},{"v":17,"t":"Acești scriitori, explicând întrebări privind Exodul, spun că toți deopotrivă trebuie să jertfească jertfele pascale după echinocțiul de primăvară, la mijlocul lunii întâi. Dar aceasta se petrece pe când soarele trece prin prima secțiune a cercului solar, sau, cum l-au numit unii dintre ei, a cercului zodiacal. Aristobul adaugă că pentru sărbătoarea Paștilor este necesar nu numai ca soarele să treacă prin secțiunea echinocțială, ci și luna."},{"v":18,"t":"Căci fiind două secțiuni echinocțiale, cea de primăvară și cea de toamnă, direct opuse una alteia, și ziua Paștilor fiind rânduită în paisprezece ale lunii, începând cu seara, luna va ține o poziție diametral opusă soarelui, cum se vede la lunile pline; și soarele va fi în secțiunea echinocțiului de primăvară, iar luna, în mod necesar, în cea a echinocțiului de toamnă."},{"v":19,"t":"Știu că multe alte lucruri au fost spuse de ei, unele probabile, iar altele apropiate de dovedire desăvârșită, prin care se străduiesc să dovedească că este cu totul necesar să se țină Paștile și sărbătoarea azimelor după echinocțiu. Dar mă abțin să cer acest fel de dovadă pentru lucruri din care a fost luat vălul Legii lui Moise, așa încât acum, în sfârșit, cu fața descoperită privim necontenit ca într-o oglindă pe Hristos și învățăturile și suferințele lui Hristos. (2 Corinteni 3:18) Dar că la evrei luna întâi era aproape de echinocțiu arată și învățăturile Cărții lui Enoh."},{"v":20,"t":"Același scriitor a lăsat și Instituțiile de aritmetică, în zece cărți, și alte dovezi ale experienței și priceperii lui în cele dumnezeiești."},{"v":21,"t":"Teotecn, episcopul Cezareei Palestinei, l-a hirotonit întâi episcop, intenționând să-l facă urmașul său în propria lui parohie după moartea sa. Și o scurtă vreme amândoi au păstorit aceeași biserică. Dar sinodul ținut pentru a cerceta cazul lui Pavel l-a chemat la Antiohia și, trecând prin cetatea Laodiceei, Eusebiu fiind mort, a fost reținut de frații de acolo."},{"v":22,"t":"Și după ce Anatolie a plecat din această viață, ultimul episcop al acelei parohii înainte de prigoană a fost Ștefan, care era admirat de mulți pentru cunoașterea filozofiei și a altor științe grecești. Dar nu era la fel de dedicat credinței dumnezeiești, după cum a arătat înaintarea prigoanei; căci aceasta a arătat că era un prefăcut fricos și nebărbătesc, mai degrabă decât un adevărat filozof."},{"v":23,"t":"Dar aceasta nu a vătămat serios biserica, căci Teodot și-a refăcut treburile, fiind îndată făcut episcop al acelei parohii chiar de Dumnezeu, Mântuitorul tuturor. A justificat prin faptele lui atât numele lui domnesc, cât și slujba de episcop. Căci excela în arta medicală pentru trupuri și în arta vindecării pentru suflete. Nici vreun alt om nu l-a egalat în bunătate, sinceritate, simpatie și râvnă în a ajuta pe cei care aveau nevoie de ajutorul lui. Era și foarte dedicat învățăturii dumnezeiești. Așa era el."},{"v":24,"t":"În Cezareea Palestinei, Agapie i-a urmat lui Teotecn, care îndeplinise cu cea mai mare râvnă îndatoririle episcopiei sale. Și pe el îl știm că a muncit cu sârguință și a arătat cea mai adevărată purtare de grijă în supravegherea poporului, îngrijindu-se mai ales de toți săracii cu mână largă."},{"v":25,"t":"În vremea lui l-am cunoscut pe Pamfil, acel om foarte elocvent, de viață cu adevărat filozofică, care a fost găsit vrednic de slujba de prezbiter în acea parohie. Nu ar fi lucru mic să arătăm ce fel de om era și de unde venea. Dar am descris, în lucrarea noastră deosebită despre el, toate amănuntele vieții lui și ale școlii pe care a întemeiat-o și încercările pe care le-a îndurat în multe mărturisiri în timpul prigoanei și cununa martiriului cu care a fost cinstit în cele din urmă. Dar dintre toți cei de acolo, el a fost cu adevărat cel mai admirabil."},{"v":26,"t":"Printre cei mai apropiați de vremurile noastre, i-am cunoscut pe Pierie, dintre prezbiterii din Alexandria, și pe Meletie, episcopul bisericilor din Pont — oameni din cei mai rari."},{"v":27,"t":"Cel dintâi se deosebea prin viața de sărăcie desăvârșită și prin învățătura filozofică și era nespus de sârguincios în contemplarea și expunerea celor dumnezeiești și în cuvântările publice din biserică. Meletie, pe care cei învățați îl numeau «mierea Atticii», era un om pe care oricine l-ar descrie ca desăvârșit în toate felurile de învățătură; și ar fi cu neputință să se admire îndeajuns priceperea lui retorică. S-ar putea spune că o avea din fire; dar cine ar putea întrece excelența marii lui experiențe și erudiții în alte privințe?"},{"v":28,"t":"Căci în toate ramurile cunoașterii, dacă ai fi încercat să-l pui la probă chiar o singură dată, ai fi spus că este cel mai iscusit și mai învățat. Mai mult, virtuțile vieții lui nu erau mai puțin remarcabile. L-am observat bine în timpul prigoanei, când șapte ani întregi scăpa de furia ei în ținuturile Palestinei."},{"v":29,"t":"Zambda a primit episcopia bisericii din Ierusalim după episcopul Imeneu, pe care l-am pomenit puțin mai sus. A murit în scurt timp și Hermon, ultimul dinaintea prigoanei din zilele noastre, a urmat în scaunul apostolic, care s-a păstrat acolo până în ziua de azi."},{"v":30,"t":"În Alexandria, lui Maxim, care, după moartea lui Dionisie, fusese episcop optsprezece ani, i-a urmat Teona. În vremea lui a devenit vestit Ahila, care fusese rânduit prezbiter în Alexandria în același timp cu Pierie. A fost pus peste școala sfintei credințe și a arătat roade de filozofie din cele mai rare și întru nimic mai prejos, și o purtare cu adevărat evanghelică."},{"v":31,"t":"După ce Teona ținuse slujba nouăsprezece ani, Petru a primit episcopia în Alexandria și a fost foarte însemnat între ei timp de doisprezece ani întregi. Dintre aceștia a păstorit biserica mai puțin de trei ani înainte de prigoană, iar restul vieții sale s-a supus unei discipline mai aspre și s-a îngrijit, nu în taină, de interesul obștesc al bisericilor. Din această pricină a fost decapitat în al nouălea an al prigoanei și a fost împodobit cu cununa martiriului."},{"v":32,"t":"Scriind în aceste cărți relatarea succesiunilor de la nașterea Mântuitorului nostru până la nimicirea locurilor de închinare — o perioadă de trei sute cinci ani —, îngăduiți-mi să trec la luptele celor care, în zilele noastre, au luptat eroic pentru religie și să las în scris, spre știința urmașilor, întinderea și măreția acelor lupte."}];
